import java.io.BufferedReader; import java.io.InputStreamReader; import java.util.StringTokenizer; import java.io.PrintWriter; import java.io.BufferedOutputStream; public class TestClass { public static void main(String[] args) throws Exception { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out)); int n = Integer.parseInt(br.readLine().trim()); StringTokenizer st = new StringTokenizer(br.readLine()); boolean[] present = new boolean[200005]; int mex = 0; for (int i = 0; i < n; i++) { int val = Integer.parseInt(st.nextToken()); if (val < 200005) { present[val] = true; } while (present[mex]) { mex++; } out.print(mex + " "); } out.flush(); out.close(); } }